css:
:root{--ca:#C8865A;--te:#B5521E;--ol:#4A5240;--cr:#F0EAD2;--cd:#E4D9BC;--sa:#D4C49A;--td:#2C2A24;--tm:#5C5448;--wh:#FDFAF4;}
*{margin:0;padding:0;box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{font-family:'Jost',sans-serif;background:var(--wh);color:var(--td);overflow-x:hidden;cursor:none;}

/* CURSOR */
#cd{width:10px;height:10px;background:var(--te);border-radius:50%;position:fixed;top:0;left:0;pointer-events:none;z-index:99999;transform:translate(-50%,-50%);box-shadow:0 0 0 2px rgba(181,82,30,.25);transition:width .2s,height .2s,background .2s;}
body.ch #cd{width:16px;height:16px;background:var(--ol);}
.trail{position:fixed;pointer-events:none;z-index:9990;animation:trOut .9s ease forwards;}
@keyframes trOut{0%{opacity:.8;transform:translate(-50%,-50%) translateY(0)}100%{opacity:0;transform:translate(-50%,-50%) translateY(-20px)}}

/* PROGRESS */
#prog{position:fixed;top:0;left:0;height:2px;background:linear-gradient(90deg,var(--ca),var(--te));z-index:9997;width:0%;}

/* NAV */
nav{background:rgba(253,250,244,.95);backdrop-filter:blur(14px);padding:16px 60px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--cd);position:sticky;top:0;z-index:100;box-shadow:0 2px 20px rgba(44,42,36,.1);}
.logo{font-family:'Cormorant Garamond',serif;font-size:22px;font-weight:600;color:var(--ol);text-decoration:none;}
.logo em{color:var(--ca);font-style:italic;}
.nav-links{display:flex;gap:32px;align-items:center;}
.nav-links a{font-size:13px;font-weight:500;color:var(--tm);text-decoration:none;letter-spacing:.06em;transition:color .3s;cursor:none;}
.nav-links a:hover{color:var(--te);}
.nav-links a.active{color:var(--te);border-bottom:1.5px solid var(--ca);padding-bottom:2px;}
.nav-cta{background:var(--te);color:var(--wh)!important;padding:9px 20px;border-radius:2px;font-size:12px!important;font-weight:600!important;letter-spacing:.1em;text-transform:uppercase;transition:background .3s!important;}
.nav-cta:hover{background:var(--ol)!important;border-bottom:none!important;}

/* HERO BLOG */
.blog-hero{background:var(--ol);padding:80px 60px;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;position:relative;overflow:hidden;}
.blog-hero::before{content:'記事';font-family:'Cormorant Garamond',serif;font-size:400px;color:rgba(255,255,255,.03);position:absolute;right:-40px;top:50%;transform:translateY(-50%);line-height:1;pointer-events:none;animation:float 10s ease-in-out infinite;}
@keyframes float{0%,100%{transform:translateY(-50%)}50%{transform:translateY(-53%)}}
.blog-hero-text{position:relative;z-index:1;}
.hero-tag{display:inline-flex;align-items:center;gap:8px;background:rgba(200,134,90,.25);border:1px solid rgba(200,134,90,.4);color:var(--sa);font-size:11px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;padding:6px 14px;border-radius:1px;margin-bottom:20px;}
.blog-hero h1{font-family:'Cormorant Garamond',serif;font-size:clamp(38px,5vw,58px);font-weight:400;line-height:1.15;color:var(--cr);margin-bottom:16px;}
.blog-hero h1 em{font-style:italic;color:var(--sa);}
.blog-hero p{font-size:16px;line-height:1.75;color:rgba(240,234,210,.75);font-weight:300;max-width:460px;}
.blog-hero-visual{position:relative;z-index:1;display:flex;justify-content:center;}
.author-card{background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);border-radius:4px;padding:28px;display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center;width:260px;transition:background .4s;}
.author-card:hover{background:rgba(255,255,255,.12);}
.author-img{width:90px;height:90px;border-radius:50%;overflow:hidden;border:3px solid rgba(200,134,90,.5);}
.author-img img{width:100%;height:100%;object-fit:cover;object-position:center 10%;}
.author-name{font-family:'Cormorant Garamond',serif;font-size:18px;font-weight:600;color:var(--cr);}
.author-title{font-size:12px;color:rgba(240,234,210,.6);letter-spacing:.06em;}
.author-stats{display:flex;gap:20px;margin-top:8px;}
.astat{text-align:center;}
.astat-n{font-family:'Cormorant Garamond',serif;font-size:22px;font-weight:600;color:var(--ca);}
.astat-l{font-size:11px;color:rgba(240,234,210,.55);}

/* FILTERS */
.filters{padding:32px 60px;background:var(--cr);border-bottom:1px solid var(--cd);display:flex;gap:12px;flex-wrap:wrap;align-items:center;}
.filter-label{font-size:11px;font-weight:600;letter-spacing:.18em;text-transform:uppercase;color:var(--tm);margin-right:8px;}
.filter-btn{padding:8px 18px;border-radius:20px;font-family:'Jost',sans-serif;font-size:12px;font-weight:500;letter-spacing:.06em;cursor:none;border:1.5px solid var(--cd);background:transparent;color:var(--tm);transition:all .3s;}
.filter-btn:hover,.filter-btn.active{background:var(--te);border-color:var(--te);color:var(--wh);}

/* ARTICLES GRID */
.blog-main{padding:60px;background:var(--wh);}
.featured-row{display:grid;grid-template-columns:2fr 1fr;gap:28px;margin-bottom:28px;}
.articles-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;}

/* ARTICLE CARD */
.card{background:var(--wh);border:1px solid var(--cd);border-radius:4px;overflow:hidden;cursor:none;transition:transform .4s cubic-bezier(.23,1,.32,1),box-shadow .4s;position:relative;}
.card:hover{transform:translateY(-8px);box-shadow:0 20px 48px rgba(44,42,36,.12);}
.card::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--ca),var(--te));transform:scaleX(0);transition:transform .4s cubic-bezier(.23,1,.32,1);}
.card:hover::after{transform:scaleX(1);}

/* featured card */
.card.featured{display:grid;grid-template-columns:1fr 1fr;}
.card.featured .card-img{height:100%;min-height:320px;}

.card-img{height:200px;overflow:hidden;position:relative;}
.card-img-bg{width:100%;height:100%;object-fit:cover;transition:transform .5s cubic-bezier(.23,1,.32,1);}
.card:hover .card-img-bg{transform:scale(1.04);}
.card-img-overlay{position:absolute;inset:0;background:linear-gradient(to bottom,transparent 40%,rgba(44,42,36,.5));pointer-events:none;}
.card-cat{position:absolute;top:14px;left:14px;background:var(--te);color:var(--wh);font-size:10px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;padding:4px 10px;border-radius:1px;}

.card-body{padding:24px;}
.card-meta{display:flex;gap:14px;align-items:center;margin-bottom:10px;}
.card-date{font-size:12px;color:var(--ca);letter-spacing:.04em;}
.card-read{font-size:12px;color:var(--tm);}
.card-read::before{content:'·';margin-right:8px;color:var(--cd);}
.card h2{font-family:'Cormorant Garamond',serif;font-size:22px;font-weight:600;line-height:1.25;color:var(--ol);margin-bottom:10px;transition:color .3s;}
.card:hover h2{color:var(--te);}
.card.featured h2{font-size:30px;}
.card p{font-size:14px;line-height:1.7;color:var(--tm);font-weight:300;margin-bottom:18px;}
.card-footer{display:flex;justify-content:space-between;align-items:center;padding-top:14px;border-top:1px solid var(--cd);}
.card-tags{display:flex;gap:6px;flex-wrap:wrap;}
.tag{font-size:10px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--ca);background:rgba(200,134,90,.1);padding:3px 8px;border-radius:1px;}
.read-btn{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--te);text-decoration:none;cursor:none;transition:gap .3s;}
.read-btn:hover{gap:10px;}
.read-btn svg{transition:transform .3s;}
.read-btn:hover svg{transform:translateX(3px);}

/* ARTICLE MODAL */
.modal-overlay{position:fixed;inset:0;background:rgba(44,42,36,.7);backdrop-filter:blur(6px);z-index:1000;opacity:0;pointer-events:none;transition:opacity .4s;}
.modal-overlay.open{opacity:1;pointer-events:all;}
.modal{position:fixed;top:0;right:0;bottom:0;width:min(680px,95vw);background:var(--wh);z-index:1001;transform:translateX(100%);transition:transform .5s cubic-bezier(.23,1,.32,1);overflow-y:auto;}
.modal.open{transform:translateX(0);}
.modal-header{padding:40px 48px 28px;border-bottom:1px solid var(--cd);position:relative;}
.modal-close{position:absolute;top:20px;right:24px;width:36px;height:36px;border:none;background:var(--cr);border-radius:50%;cursor:none;display:flex;align-items:center;justify-content:center;transition:background .3s;font-size:18px;color:var(--tm);}
.modal-close:hover{background:var(--cd);}
.modal-cat{font-size:11px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:var(--ca);margin-bottom:12px;}
.modal-title{font-family:'Cormorant Garamond',serif;font-size:clamp(26px,3.5vw,38px);font-weight:500;color:var(--ol);line-height:1.2;margin-bottom:16px;}
.modal-title em{font-style:italic;color:var(--te);}
.modal-meta{display:flex;gap:16px;font-size:13px;color:var(--tm);}
.modal-body{padding:36px 48px 60px;}
.modal-body p{font-size:16px;line-height:1.85;color:var(--tm);margin-bottom:20px;font-weight:300;}
.modal-body h3{font-family:'Cormorant Garamond',serif;font-size:24px;font-weight:600;color:var(--ol);margin:32px 0 12px;}
.modal-body blockquote{border-left:3px solid var(--ca);padding:16px 20px;background:var(--cr);margin:24px 0;font-family:'Cormorant Garamond',serif;font-size:19px;font-style:italic;color:var(--ol);line-height:1.6;}
.modal-body ul{list-style:none;margin:16px 0;display:flex;flex-direction:column;gap:10px;}
.modal-body ul li{font-size:15px;color:var(--tm);display:flex;gap:10px;line-height:1.6;font-weight:300;}
.modal-body ul li::before{content:'◆';color:var(--ca);font-size:7px;margin-top:6px;flex-shrink:0;}
.modal-cta{margin-top:40px;padding:28px;background:var(--ol);border-radius:3px;text-align:center;}
.modal-cta p{font-size:14px;color:rgba(240,234,210,.8);margin-bottom:14px;font-weight:300;}
.modal-cta a{display:inline-flex;align-items:center;gap:8px;background:var(--te);color:var(--wh);padding:12px 28px;border-radius:2px;font-size:13px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;text-decoration:none;transition:background .3s;cursor:none;}
.modal-cta a:hover{background:var(--ca);}

/* NEWSLETTER */
.newsletter{background:var(--cr);padding:60px;display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;border-top:1px solid var(--cd);}
.nl-text h2{font-family:'Cormorant Garamond',serif;font-size:clamp(28px,3.5vw,40px);font-weight:500;color:var(--ol);line-height:1.2;margin-bottom:12px;}
.nl-text h2 em{font-style:italic;color:var(--te);}
.nl-text p{font-size:15px;color:var(--tm);line-height:1.7;font-weight:300;}
.nl-form{display:flex;flex-direction:column;gap:12px;}
.nl-form input{padding:13px 16px;border:1.5px solid var(--cd);border-radius:2px;font-family:'Jost',sans-serif;font-size:14px;background:var(--wh);outline:none;transition:border-color .3s,box-shadow .3s;cursor:none;}
.nl-form input:focus{border-color:var(--ca);box-shadow:0 0 0 3px rgba(200,134,90,.12);}
.nl-form button{background:var(--te);color:var(--wh);border:none;padding:14px;border-radius:2px;font-family:'Jost',sans-serif;font-size:13px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;cursor:none;transition:background .3s;}
.nl-form button:hover{background:var(--ol);}

/* FOOTER */
.blog-footer{background:var(--td);color:var(--cr);padding:32px 60px;display:flex;justify-content:space-between;align-items:center;font-size:13px;}
.blog-footer a{color:var(--ca);text-decoration:none;cursor:none;}
.back-funnel{display:inline-flex;align-items:center;gap:8px;background:var(--te);color:var(--wh);padding:9px 20px;border-radius:2px;font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;text-decoration:none;cursor:none;transition:background .3s;}
.back-funnel:hover{background:var(--ca);}

@media(max-width:900px){
  body{cursor:auto;}#cd{display:none;}
  nav{padding:14px 24px;}.nav-links{gap:16px;}.nav-links .nav-cta{display:none;}
  .blog-hero{grid-template-columns:1fr;padding:50px 24px;}.blog-hero-visual{display:none;}
  .filters{padding:20px 24px;}
  .blog-main{padding:32px 24px;}
  .featured-row{grid-template-columns:1fr;}.card.featured{grid-template-columns:1fr;}
  .articles-grid{grid-template-columns:1fr;}
  .newsletter{grid-template-columns:1fr;padding:40px 24px;gap:32px;}
  .blog-footer{padding:24px;flex-direction:column;gap:16px;text-align:center;}
  .modal{width:100%;top:10%;}
  .modal-header,.modal-body{padding:28px 24px 40px;}
}
